steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{"query": "{ teamType: __type(name: \"Team\") { fields { name arguments { name type { name kind ofType { name kind } } } } } userType: __type(name: \"User\") { fields { name arguments { name type { name kind ofType { name kind } } } } } }"}' | python3 -c "
import json, sys
data = json.load(sys.stdin)
for field in data['data']['teamType']['fields']:
    if field['name'] in ('memberships', 'members'):
        print(f\"Team.{field['name']}: args = {field['arguments']}\")
for field in data['data']['userType']['fields']:
    if field['name'] == 'teamMemberships':
        print(f\"User.{field['name']}: args = {field['arguments']}\")
"
